        return grid

    rows = len(grid)
    cols = len(grid[0])

    # visited map
    visited = [[False] * cols for _ in range(rows)]
    components = []  # list of components, each a list of (r,c) positions

    # Find all zero-components using DFS/BFS
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                comp = []
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == 0:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                components.append(comp)

    # Identify the largest component (the "outside")
    max_size = -1
    largest = None
    for comp in components:
        if len(comp) > max_size:
            max_size = len(comp)
            largest = comp

    # Build output grid
    out = [row[:] for row in grid]

    # Fill all components except the largest with 4
    for comp in components:
        if comp is not largest:
            for r, c in comp:
                out[r][c] = 4

